import com.mirrorlink.mobile.ConnectionHistory;import java.io.*;import java.util.Base64;
public class HistoryMetadataTest {public static void main(String[] args)throws Exception{ConnectionHistory h=new ConnectionHistory();h.record("192.168.1.8:52345","001234",10);h.rename("192.168.1.8:52345","工作电脑");h.favorite("192.168.1.8:52345",true);h.record("192.168.1.8:52345","",20);ConnectionHistory.Entry e=ConnectionHistory.decode(h.encode()).entries().get(0);if(!e.favorite||!e.name.equals("工作电脑")||!e.fixedCode.isEmpty())throw new AssertionError();ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(b);d.writeInt(1);d.writeInt(1);d.writeUTF("192.168.1.8:52345");d.writeUTF("001234");d.writeLong(10);e=ConnectionHistory.decode(Base64.getEncoder().encodeToString(b.toByteArray())).entries().get(0);if(!e.name.isEmpty()||e.favorite)throw new AssertionError("migration");try{h.rename(e.address,"a\nb");throw new AssertionError("control chars");}catch(IllegalArgumentException expected){}System.out.println("PASS history metadata and migration");}}
